    // ============================================================
    function _vnTodayUtcMs() {
        var now = new Date(Date.now() + 7 * 3600 * 1000);
        return Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
    }
    function _countdownAnnual(month, day, name) {
        var today = _vnTodayUtcMs();
        var year = new Date(today).getUTCFullYear();
        var target = Date.UTC(year, month - 1, day);
        if (target < today) target = Date.UTC(year + 1, month - 1, day);
        var diff = Math.round((target - today) / 86400000);
        return diff === 0 ? ("Hôm nay là " + name + " 🎉") : ("Còn " + diff + " ngày nữa tới " + name);
    }
    function _countdownDates(dates, name) {
        var today = _vnTodayUtcMs();
        for (var i = 0; i < dates.length; i++) {
            var target = Date.UTC(dates[i][0], dates[i][1] - 1, dates[i][2]);
            if (target >= today) {
                var diff = Math.round((target - today) / 86400000);
                return diff === 0 ? ("Hôm nay là " + name + " 🎉") : ("Còn " + diff + " ngày nữa tới " + name);
            }
        }
        return name;
    }

